import fs from "node:fs";
import path from "node:path";
import process from "node:process";

const root = process.cwd();
const read = (relativePath) => fs.readFileSync(path.join(root, relativePath), "utf8");

const sources = new Map();
function source(relativePath) {
  if (!sources.has(relativePath)) {
    sources.set(relativePath, read(relativePath));
  }
  return sources.get(relativePath);
}

const checks = [];
const failures = [];

function addCheck(label, passed, detail) {
  checks.push(label);
  if (!passed) {
    failures.push({ label, detail });
  }
}

function mustContain(relativePath, needle, label) {
  addCheck(label, source(relativePath).includes(needle), `${relativePath} should contain ${needle}`);
}

function mustNotContain(relativePath, needle, label) {
  addCheck(label, !source(relativePath).includes(needle), `${relativePath} should not contain ${needle}`);
}

function mustMatch(relativePath, pattern, label) {
  addCheck(label, pattern.test(source(relativePath)), `${relativePath} should match ${pattern}`);
}

